package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many existing owners already share the new owner's first and last name,
 * case-insensitively, at the moment of creation. Runs after {@link BuildOwner} has produced
 * the entity and before {@link SaveOwner} persists it, so {@code findAll()} sees only the
 * owners that existed before this create; the count is stored on the owner and returned on
 * every later read.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}
===== AssignHouseholdId =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's household identifier before it is saved. The id is derived from the
 * owner's last name and address via {@link HouseholdKey#id(String, String)}, so every owner of
 * the same household receives the same stable value. Runs after {@link BuildOwner} has produced
 * the entity and before {@link SaveOwner} persists it, mutating the built owner in place.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(HouseholdKey.id(owner.getLastName(), owner.getAddress()));
    }
}
===== ValidateOwnerPostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
import org.springframework.samples.petclinic.util.Postcodes;

/**
 * Validates an optional postcode on an owner request. Postcode is not required: a null or
 * blank value is left untouched. When present it must be a 4-digit value valid for the owner's
 * city region (see {@link Postcodes}), otherwise the request is rejected with
 * {@link InvalidPostcodeException} (400).
 */
public class ValidateOwnerPostcode {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        if (!Postcodes.isValidForCity(request.getCity(), postcode)) {
            throw new InvalidPostcodeException(postcode, request.getCity());
        }
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        built.set(ownerMapper.toOwner(request));
    }
}
